const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([49.30, -12.28]); // Arrachart, Madagascar
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';
  const thresholdInches = 22;
  const thresholdMm = thresholdInches * 25.4;

  // 2. Data Acquisition & Check
  // Using CHIRPS Daily for precipitation data.
  let chirpsCollection = ee.ImageCollection('UCSB-CHIRPS/DAILY')
    .filterBounds(point)
    .filterDate(startDate, endDate);

  const collectionSize = chirpsCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No images found for the specified date range.");
    console.log("Evidence: CHIRPS collection size is 0.");
    console.log("A: No"); // It did not recieve rainfall if there is no data
    return;
  }

  // 3. Processing
  // Sum all daily images in the collection to get a total monthly rainfall image.
  const totalPrecipitation = chirpsCollection.select('precipitation').sum();

  // 4. Calculation
  // Extract the total rainfall value at the specified point.
  // Using a small scale since it's a point extraction from a 5km product.
  const rainfallStats = totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point,
    scale: 5000, // CHIRPS native resolution is ~5.5km
    maxPixels: 1e9
  });

  const rainfallMm = rainfallStats.get('precipitation').getInfo();

  // 5. Validation & Final Answer
  if (rainfallMm === null || rainfallMm === undefined) {
    console.log("Calculation Failure: Could not extract rainfall value at the location.");
    console.log("The point may be over a water body or outside data coverage.");
    console.log("C3");
    return;
  }

  const rainfallInches = rainfallMm / 25.4;

  console.log(`Location: Arrachart, Madagascar`);
  console.log(`Period: ${startDate} to ${endDate}`);
  console.log(`Image Count: ${collectionSize}`);
  console.log(`Threshold: > ${thresholdInches} inches (${thresholdMm.toFixed(2)} mm)`);
  console.log(`Total Rainfall: ${rainfallMm.toFixed(2)} mm`);
  console.log(`Total Rainfall: ${rainfallInches.toFixed(2)} inches`);

  if (rainfallMm > thresholdMm) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error("An error occurred:", err);
  console.log("D");
});
